328	func convertLocationFromStore(location *storepb.MemoPayload_Location) *v1pb.Location {
329		if location == nil {
330			return nil
331		}
332		return &v1pb.Location{
333			Placeholder: location.Placeholder,
334			Latitude:    location.Latitude,
335			Longitude:   location.Longitude,
336		}
